//! Canonical HTMLElement identity for the fixed historical HTML names.
//! https://html.spec.whatwg.org/multipage/dom.html#elements-in-the-dom
use super::*;
const TAGS:&str="['acronym','basefont','big','center','nobr','noembed','noframes','plaintext','rb','rtc','strike','tt']";
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><center id=historical class=initial></center><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://historical-html.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn historical_html_actual_native_factories_and_canonical_prototypes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("for(var tag of {TAGS}){{var x=document.createElement(tag.toUpperCase());if(Object.getPrototypeOf(x)!==HTMLElement.prototype||x.constructor!==HTMLElement||!(x instanceof HTMLElement)||!(x instanceof Element)||!(x instanceof Node)||x instanceof HTMLUnknownElement||x.localName!==tag||x.namespaceURI!=='http://www.w3.org/1999/xhtml'||x.ownerDocument!==document||Object.prototype.toString.call(x)!=='[object HTMLElement]')throw 'native historical HTML interface '+tag;}}"));}
#[test]
fn historical_html_shared_classifier_is_exact(){for tag in ["acronym","basefont","big","center","nobr","noembed","noframes","plaintext","rb","rtc","strike","tt"]{assert_eq!(crate::javascript::ordinary_html_interface(tag),Some("HTMLElement"),"{tag}");assert_ne!(crate::javascript::ordinary_html_interface(&tag.to_ascii_uppercase()),Some("HTMLElement"),"exact local name {tag}");}}
#[test]
fn historical_html_inert_explicit_namespace_and_foreign_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var doc=new Document();for(var tag of {TAGS}){{var x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:'+tag),y=doc.createElementNS('urn:foreign',tag),upper=doc.createElementNS('http://www.w3.org/1999/xhtml',tag.toUpperCase());if(Object.getPrototypeOf(x)!==HTMLElement.prototype||x.constructor!==HTMLElement||!(x instanceof HTMLElement)||x instanceof HTMLUnknownElement||x.localName!==tag||x.prefix!=='t'||x.ownerDocument!==doc||y instanceof HTMLElement||y instanceof HTMLUnknownElement||upper.localName!==tag.toUpperCase())throw 'inert historical exact namespace '+tag;}}"));}
#[test]
fn historical_html_inherited_attributes_are_actual_exact_handles(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document();for(var x of [document.getElementById('historical'),doc.createElementNS('http://www.w3.org/1999/xhtml','t:center')]){x.id='before';var a=x.getAttributeNode('id'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.id='A\ud800Z';var records=watch.takeRecords();if(x.id!=='A\ud800Z'||a.value!==x.id||x.getAttributeNode('id')!==a||records.length!==1||records[0].oldValue!=='before'||Object.getPrototypeOf(x)!==HTMLElement.prototype)throw 'actual historical attribute';x.removeAttribute('id');if(a.ownerElement!==null||a.value!=='A\ud800Z'||x.id!=='')throw 'historical attribute removal';}"#);}
#[test]
fn historical_html_saved_global_and_wrong_concrete_brands(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var C=HTMLElement,P=C.prototype,x=document.getElementById('historical'),a=Object.getOwnPropertyDescriptor(HTMLFontElement.prototype,'color'),id=Object.getOwnPropertyDescriptor(Element.prototype,'id'),calls=0;delete window.HTMLElement;window.HTMLElement=function Fake(){};for(var y of [x,document.createElement('center'),new Document().createElementNS('http://www.w3.org/1999/xhtml','tt')]){if(!(y instanceof C)||Object.getPrototypeOf(y)!==P||y instanceof window.HTMLElement)throw 'saved historical canonical interface';var caught=false;try{a.set.call(y,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'historical has no font authority';}for(var bad of [{},Object.create(P)]){var caught=false;try{id.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'historical prototype grants no native authority';}");}
#[test]
fn historical_html_captured_origin_refusal_and_recovery(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('historical'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLElement,a=Object.getOwnPropertyDescriptor(frame.contentWindow.Element.prototype,'id'),calls=0;if(C===HTMLElement||a.get.call(x)!=='historical')throw 'real child historical interface';");p.set_location(&crate::navigation::address("https://other-historical-html.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for s in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(s,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://historical-html.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'historical origin precedes hooks';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered'||Object.getPrototypeOf(x)!==HTMLElement.prototype)throw 'historical origin recovery';");}
